test_that("MV17-G full calibration is prospectively frozen without public identities", {
  root<-testthat::test_path("..","..");a<-file.path(root,"docs","audits","mv17g-full-calibration-prefreeze-v1");skip_if_not(dir.exists(a),"MV17-G calibration prefreeze absent");r<-function(n)read.csv(file.path(a,n),stringsAsFactors=FALSE,check.names=FALSE);v<-r("mv17g-validation.csv");c<-r("mv17g-contract.csv");b<-r("mv17g-private-binding.csv");q<-r("mv17g-queue-summary.csv");m<-r("mv17g-artifact-manifest.csv");expect_equal(nrow(v),25L);expect_true(all(v$passed));expect_equal(c$replicates,99L);expect_equal(c$minimum_attainable_probability,.01);expect_true(c$full_calibration_authorized_after_commit);expect_false(c$full_calibration_authorized);expect_false(c$real_localization_authorized);expect_equal(b$rows,c(264L,1188L,27L,91476L));expect_false(any(c("unit_id","identity_token","source_path","accepted_diagram_sha256")%in%names(q)));files<-file.path(a,m$artifact);expect_equal(as.numeric(file.info(files)$size),m$bytes);expect_equal(unname(vapply(files,digest::digest,character(1L),algo="sha256",file=TRUE,serialize=FALSE)),unname(m$sha256))
})
